-- ============================================================================
-- DH1 RESTRUCTURE — tái cấu trúc khoá "Khởi đầu đam mê — Đệm hát cơ bản" theo
-- giáo trình sách Đệm hát 1 (5 Level). SINH TỰ ĐỘNG từ db/gen_dh1.cjs — ĐỪNG SỬA TAY.
-- Chạy trên Supabase SQL editor. Idempotent (lookup khoá theo tên, module theo
-- tên/id, bài theo UUID cố định d1c00...). Xoá hẳn 3 chương cũ ở cuối file.
-- CHẠY SAU qr_links_demhat.sql (slug QR phải tồn tại trước — đuôi file UPDATE
--   target QR về đúng lesson id; chạy khi chưa có slug thì QR không trỏ được).
-- ============================================================================
DO $$
DECLARE
  v_course uuid;
  v_mod    uuid;
  v_les    uuid;
BEGIN
  SELECT id INTO v_course FROM edu_courses WHERE name ILIKE '%Đệm hát cơ bản%' LIMIT 1;
  IF v_course IS NULL THEN RAISE EXCEPTION 'Không tìm thấy khoá "Đệm hát cơ bản"'; END IF;

  -- ===== Level 1: Một hợp âm · Quạt đều · Nghe chủ động =====
  SELECT id INTO v_mod FROM edu_modules WHERE course_id = v_course AND name ILIKE 'Level 1%' LIMIT 1;
  IF v_mod IS NULL THEN
    INSERT INTO edu_modules (course_id, name, order_index) VALUES (v_course, 'Level 1: Một hợp âm · Quạt đều · Nghe chủ động', 1) RETURNING id INTO v_mod;
  ELSE
    UPDATE edu_modules SET name = 'Level 1: Một hợp âm · Quạt đều · Nghe chủ động', order_index = 1 WHERE id = v_mod;
  END IF;

  -- Bài 1.1 — Am, một tiếng sạch  (dh11)
  v_les := 'd1c00101-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 1.1 — Am, một tiếng sạch', 'flow', 0, 'free', '[]'::jsonb, 'qr:dh11')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 0, content_url = 'qr:dh11';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 1.1 — Am, một tiếng sạch', 20, 'published', $json$[{"id":"s1","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Cầm đàn thoải mái, vai và tay thả lỏng. Bấm Am rồi gảy lần lượt từng dây (dây 5, 4, 3, 2, 1). Nghe xem dây nào kêu trong, dây nào bị tịt hoặc rè.</p>"},{"id":"s2","order":2,"logic":"NHAN","type":"guitar_chord","title":"Hợp âm Am","interactive":{"name":"Am","frets":[-1,0,2,2,1,0],"freqs":[0,110,164.81,220,261.63,329.63],"caption":"Am (La thứ) — bass ở dây 5. Ngón 1 dây 2/f1, ngón 2 dây 4/f2, ngón 3 dây 3/f2. Ba mẹo để dây kêu sạch: đặt đầu ngón sát bên trái thanh phím; dựng ngón thẳng đứng; bấm bằng đầu ngón, đủ lực nhưng không gồng. Bấm <b>Nghe</b> rồi gảy thử trên đàn."}},{"id":"s3","order":3,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>“Tiếng sạch” là mọi dây trong hợp âm đều kêu rõ — không dây nào bị <b>tịt</b> (không kêu) hay <b>rè</b> (rẹt rẹt). Dây tịt thường do bấm chưa đủ lực hoặc bụng ngón chạm dây; dây rè do ngón chưa sát phím.</p>"},{"id":"s4","order":4,"logic":"NHAN","type":"text","title":"④ Nghe","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>🎧 Trên App</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'>Nghe hai mẫu — một tiếng Am sạch và một tiếng Am bị tịt — tập phân biệt tới khi nghe ra ngay. Có <b>video hướng dẫn mẫu</b> cách bấm Am sạch.</div></div>"},{"id":"s5","order":5,"logic":"LAM","type":"guitar_strum","title":"⑤ Làm — gảy rời 5 dây của Am","interactive":{"sequence":[5,4,3,2,1]}},{"id":"s6","order":6,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Bấm Am và quạt xuống một cái — cả 5 dây kêu rõ, tiếng gọn, không rè, không tịt.</b></div></div>"}]$json$::jsonb);

  -- Bài 1.2 — Quạt đều như nhịp tim  (dh12)
  v_les := 'd1c00102-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 1.2 — Quạt đều như nhịp tim', 'flow', 1, 'free', '[]'::jsonb, 'qr:dh12')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 1, content_url = 'qr:dh12';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 1.2 — Quạt đều như nhịp tim', 20, 'published', $json$[{"id":"s7","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Trước khi cầm đàn, vỗ tay đều như tiếng đồng hồ tích – tắc – tích – tắc. Giữ các tiếng vỗ cách nhau bằng nhau. Đó chính là “đều”.</p>"},{"id":"s8","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Mỗi tiếng đều đó là một <b>phách</b> — ta chơi bằng một nốt đen. Mỗi phách quạt xuống một cái, vừa quạt vừa đếm thành tiếng: 1 – 2 – 3 – 4.</p>"},{"id":"s9","order":3,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>“Đều” có hai phần: khoảng cách giữa các lần quạt bằng nhau, và độ mạnh gần như nhau. Metronome là “nhịp tim” của buổi tập — giữ khoảng cách luôn đều để tai bạn rảnh mà lắng nghe.</p>"},{"id":"s10","order":4,"logic":"LAM","type":"guitar_metronome","title":"Metronome","interactive":{"tempo":70,"beatsPerBar":4,"caption":"④⑤ Bật metronome ở khoảng 60. Quạt sao cho tiếng đàn rơi đúng vào tiếng “click”, đếm 1–2–3–4 theo. Khi quen thì tăng dần 70 → 80."}},{"id":"s11","order":5,"logic":"LAM","type":"guitar_strumscore","title":"Strum Score","interactive":{"chords":["Am","Am","Am","Am"],"beatsPerBar":4,"tempo":60,"freqsList":[[110,164.81,220,261.63,329.63],[110,164.81,220,261.63,329.63],[110,164.81,220,261.63,329.63],[110,164.81,220,261.63,329.63]],"caption":"Bấm ▶ — ô phách sáng chạy theo nhịp, phách 1 tự gảy Am. Quạt xuống mỗi phách sao cho khớp ô đang sáng."}},{"id":"s12","order":6,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Quạt nốt đen đều, khớp metronome, giữ liên tục ít nhất 16 nhịp; miệng đếm 1–2–3–4 không rối.</b></div></div>"}]$json$::jsonb);

  -- Bài 1.3 — Nghe cả khối hợp âm  (dh13)
  v_les := 'd1c00103-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 1.3 — Nghe cả khối hợp âm', 'flow', 2, 'free', '[]'::jsonb, 'qr:dh13')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 2, content_url = 'qr:dh13';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 1.3 — Nghe cả khối hợp âm', 20, 'published', $json$[{"id":"s13","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Quạt Am một cái, rồi nhắm mắt và im lặng nghe. Đừng quạt tiếp. Nghe cho tới khi tiếng đàn tắt hẳn. Tiếng ngân kéo dài bao lâu?</p>"},{"id":"s14","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Mỗi lần quạt tạo ra một “đám mây âm thanh” gồm nhiều dây hoà quyện. Việc của bạn là hướng tai vào cả khối âm đó và nghe nó trọn vẹn — chưa cần tách riêng dây nào.</p>"},{"id":"s15","order":3,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Người mới thường “chơi cho xong” rồi vội quạt cái tiếp theo, nên chưa bao giờ thật sự nghe hợp âm của mình. Nghe được cả khối âm cho tới khi tắt là bước đầu của tai nghe chủ động.</p>"},{"id":"s16","order":4,"logic":"LAM","type":"guitar_drone","title":"Ngân dài Am","interactive":{"name":"Am","freqs":[110,164.81,220,261.63,329.63],"seconds":12,"caption":"Bấm nút để Am ngân dài. Nghe trọn tiếng ngân tới khi tắt — thử đếm xem bạn còn nghe được âm trong bao nhiêu giây."}},{"id":"s17","order":5,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Quạt Am và nghe trọn khối âm cho tới khi tắt, nói được lúc nào tiếng còn vang, lúc nào đã hết.</b></div></div>"}]$json$::jsonb);

  -- Bài 1.4 — Đi vào bên trong: dây trầm và dây 1  (dh14)
  v_les := 'd1c00104-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 1.4 — Đi vào bên trong: dây trầm và dây 1', 'flow', 3, 'free', '[]'::jsonb, 'qr:dh14')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 3, content_url = 'qr:dh14';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 1.4 — Đi vào bên trong: dây trầm và dây 1', 20, 'published', $json$[{"id":"s18","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Quạt Am và nghe cả khối như bài trước. Bây giờ thử “tìm” trong khối âm đó dây trầm nhất — dây nghe dày và thấp nhất.</p>"},{"id":"s19","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Với Am, dây thấp nhất đang vang là <b>dây 5 — nốt La</b>. Dây cao nhất là <b>dây 1 — nốt Mi</b>. Đây là hai “mỏ neo” để tai bám vào hai đầu của khối âm.</p>"},{"id":"s20","order":3,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Nghe chủ động là: hướng chú ý vào MỘT dây trong khi vẫn nghe cả khối. Cùng lúc, đọc tên dây/nốt bằng miệng để tai và trí nhớ gắn tên vào âm thanh.</p>"},{"id":"s21","order":4,"logic":"LAM","type":"guitar_ear","title":"④ Nghe & đoán: dây trầm (5) hay dây 1?","interactive":{"pool":[5,1],"rounds":6,"passScore":4}},{"id":"s22","order":5,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Nghe và gọi đúng dây trầm nhất (dây 5 · La) và dây 1 (Mi) khoảng 4/5 lần, trong khi vẫn nghe được cả khối.</b></div></div>"}]$json$::jsonb);

  -- Bài 1.5 — “Ừm…” giọng hoà vào đàn  (dh15)
  v_les := 'd1c00105-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 1.5 — “Ừm…” giọng hoà vào đàn', 'flow', 4, 'free', '[]'::jsonb, 'qr:dh15')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 4, content_url = 'qr:dh15';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 1.5 — “Ừm…” giọng hoà vào đàn', 20, 'published', $json$[{"id":"s23","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Quạt Am, rồi ngân bằng giọng một âm “ừm…” bất kỳ. Nghe xem giọng bạn có êm với tiếng đàn không, hay nghe cấn.</p>"},{"id":"s24","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Một âm “hợp” nghe êm, như tan vào tiếng đàn. Một âm “chỏi” nghe cấn tai, chông chênh. Nếu đang chỏi, nhích giọng lên/xuống một chút để tìm âm hợp.</p>"},{"id":"s25","order":3,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Khi ngân, giọng bạn giống như một dây đàn nữa cộng thêm vào hợp âm. Đây là bước đầu để sau này tiếng đàn hoà vào tiếng hát của bạn.</p>"},{"id":"s26","order":4,"logic":"LAM","type":"guitar_drone","title":"Ngân dài Am","interactive":{"name":"Am","freqs":[110,164.81,220,261.63,329.63],"seconds":14,"caption":"Cho Am ngân dài rồi ngân giọng “ừm” bám theo tiếng đàn. Tìm âm nghe êm (tan vào tiếng đàn), tránh âm cấn tai."}},{"id":"s27","order":5,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Ngân được ít nhất 2 âm hoà hợp với Am và tự nhận ra khi nào âm của mình hợp, khi nào chỏi.</b></div></div>"}]$json$::jsonb);

  -- Bài 1.6 — Ghép lại: quạt · đếm · nghe · ừm  (dh16)
  v_les := 'd1c00106-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 1.6 — Ghép lại: quạt · đếm · nghe · ừm', 'flow', 5, 'free', '[]'::jsonb, 'qr:dh16')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 5, content_url = 'qr:dh16';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 1.6 — Ghép lại: quạt · đếm · nghe · ừm', 30, 'published', $json$[{"id":"s28","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Thử làm mọi thứ cùng lúc: quạt đều, đếm 1–2–3–4, nghe dây, thỉnh thoảng ngân. Thấy quá tải là bình thường — ta ghép từng lớp.</p>"},{"id":"s29","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Khi quá tải, có thứ tự ưu tiên: <b>giữ nhịp trước, nghe sau</b>. Thà nghe ít mà tay vẫn đều, còn hơn nghe kỹ mà rớt nhịp.</p>"},{"id":"s30","order":3,"logic":"LAM","type":"guitar_metronome","title":"Metronome","interactive":{"tempo":70,"beatsPerBar":4,"caption":"⑤ Bật metronome, chạy bài ghép theo lớp: (1) quạt đều → (2) thêm đếm → (3) thêm nghe một dây → (4) thỉnh thoảng ngân một âm hợp. Rớt nhịp thì bỏ bớt một lớp rồi thêm lại."}},{"id":"s31","order":4,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Giữ quạt đều và đếm suốt 8 ô nhịp, xen kẽ nghe được dây hoặc ngân một âm hợp, mà không rớt nhịp.</b></div></div>"}]$json$::jsonb);

  -- Tự kiểm Level 1  (dh1check)
  v_les := 'd1c00199-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Tự kiểm Level 1', 'flow', 6, 'free', '[]'::jsonb, 'qr:dh1check')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 6, content_url = 'qr:dh1check';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Tự kiểm Level 1', 20, 'published', $json$[{"id":"s32","order":1,"logic":"DAN","type":"text","title":"Tự kiểm","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Đánh dấu khi bạn làm được</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'>Chỗ nào chưa đạt, quay lại đúng bài rèn năng lực đó. Khi cả bảng đều đạt, bạn sẵn sàng cho Level tiếp theo.</div></div>"},{"id":"s33","order":2,"logic":"NGAM","type":"checklist","title":"Bảng tự kiểm","interactive":{"items":["N1 — Bấm Am, cả 5 dây kêu rõ, không rè","N2 — Quạt xuống cả khối, tiếng gọn rõ","N3 — Quạt nốt đen đều ≥ 16 nhịp liên tục","N4 — Vừa quạt vừa đếm 1–2–3–4 khớp click","N5 — Nghe trọn khối âm tới khi tắt","N6 — Nghe & gọi đúng dây thấp nhất (dây 5 · La)","N7 — Nghe & gọi đúng dây 1 (Mi)","N8 — Đọc tên dây/nốt trong khi vẫn nghe","N9 — Ngân ≥ 2 âm hoà hợp với Am, nhận ra hợp/chỏi"]}}]$json$::jsonb);

  -- ===== Level 2: Đổi hai hợp âm · Nhịp không vỡ =====
  SELECT id INTO v_mod FROM edu_modules WHERE course_id = v_course AND name ILIKE 'Level 2%' LIMIT 1;
  IF v_mod IS NULL THEN
    INSERT INTO edu_modules (course_id, name, order_index) VALUES (v_course, 'Level 2: Đổi hai hợp âm · Nhịp không vỡ', 2) RETURNING id INTO v_mod;
  ELSE
    UPDATE edu_modules SET name = 'Level 2: Đổi hai hợp âm · Nhịp không vỡ', order_index = 2 WHERE id = v_mod;
  END IF;

  -- Bài 2.1 — Hai thế & tư duy ngón  (dh21)
  v_les := 'd1c00201-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 2.1 — Hai thế & tư duy ngón', 'flow', 0, 'free', '[]'::jsonb, 'qr:dh21')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 0, content_url = 'qr:dh21';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 2.1 — Hai thế & tư duy ngón', 20, 'published', $json$[{"id":"s34","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Bấm Am, rồi bấm C, rồi lại Am. Chưa cần nhanh. Quan sát: ngón nào phải nhấc lên, ngón nào giữ nguyên, ngón nào đi xa nhất?</p>"},{"id":"s35","order":2,"logic":"NHAN","type":"guitar_chord","title":"Hợp âm C","interactive":{"name":"C","frets":[-1,3,2,0,1,0],"freqs":[0,130.81,164.81,196,261.63,329.63],"caption":"C (Đô trưởng) — bass ở dây 5. Ngón 1 dây 2/f1, ngón 2 dây 4/f2, ngón 3 dây 5/f3. Bí mật khiến Am↔C dễ: ngón 1 (dây 2) và ngón 2 (dây 4) GIỮ NGUYÊN ở cả hai hợp âm; chỉ ngón 3 di từ dây 3 sang dây 5. Bấm <b>Nghe</b> rồi gảy thử trên đàn."}},{"id":"s36","order":3,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Đây là “tư duy ngón trụ”: đừng nhấc cả bàn tay rồi đặt lại. Tìm ngón nào ở yên làm điểm tựa, ngón nào di ít nhất. Tay đi ít thì đổi nhanh và nhịp không vỡ.</p>"},{"id":"s37","order":4,"logic":"NHAN","type":"text","title":"④ Nghe","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>🎧 Trên App</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'>Nghe mẫu C sạch; vừa bấm vừa nghe: khi ghì quá chặt tiếng có gì khác so với bấm vừa đủ? Có <b>video hướng dẫn mẫu</b> ngón trụ Am↔C.</div></div>"},{"id":"s38","order":5,"logic":"LAM","type":"embedded_tool","title":"Luyện hợp âm C","content":"Luyện hợp âm C","interactive":{"url":"https://chords-vananhaudio.netlify.app?chord=C"}},{"id":"s39","order":6,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Đổi được Am ↔ C với ngón 1 và ngón 2 giữ nguyên làm điểm tựa, chỉ ngón 3 di; bấm vừa đủ lực.</b></div></div>"}]$json$::jsonb);

  -- Bài 2.2 — Nhấc & chuẩn bị: vào đúng phách  (dh22)
  v_les := 'd1c00202-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 2.2 — Nhấc & chuẩn bị: vào đúng phách', 'flow', 1, 'free', '[]'::jsonb, 'qr:dh22')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 1, content_url = 'qr:dh22';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 2.2 — Nhấc & chuẩn bị: vào đúng phách', 20, 'published', $json$[{"id":"s40","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Đổi Am → C nhưng cố ý đợi đến khi cần mới nhấc ngón. Bạn sẽ thấy hợp âm mới luôn vào trễ. Vấn đề không phải tay chậm — mà là chuẩn bị quá muộn.</p>"},{"id":"s41","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Một ô nhịp có 4 phách. Hợp âm mới cần vang ở phách 1 của ô sau. Muốn vậy, tay trái phải bắt đầu chuẩn bị ngay <b>sau phách 4</b> của ô trước — không đợi đến phách 1.</p>"},{"id":"s42","order":3,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Ngón 3 rời dây 3 và “bay” sang dây 5 trong khoảng lặng ngắn sau phách 4, để đúng phách 1 nó đã ở chỗ mới. Đếm “…4-và-1”: chữ “và” là lúc ngón bắt đầu bay.</p>"},{"id":"s43","order":4,"logic":"LAM","type":"guitar_metronome","title":"Metronome","interactive":{"tempo":70,"beatsPerBar":4,"caption":"④⑤ Metronome ~60. Tập |Am · · · | C · · · | thật chậm, bắt đầu chuyển ngay sau phách 4; nghe C có vang đúng tiếng click phách 1 không. Có <b>video hướng dẫn mẫu</b> ngón bay."}},{"id":"s44","order":5,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Hợp âm mới vang đúng phách 1, nhờ đã bắt đầu chuẩn bị từ sau phách 4.</b></div></div>"}]$json$::jsonb);

  -- Bài 2.3 — Tay phải không đứt  (dh23)
  v_les := 'd1c00203-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 2.3 — Tay phải không đứt', 'flow', 2, 'free', '[]'::jsonb, 'qr:dh23')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 2, content_url = 'qr:dh23';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 2.3 — Tay phải không đứt', 20, 'published', $json$[{"id":"s45","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Quạt đều Am theo metronome, rồi thử đổi sang C. Rất có thể tay phải khựng lại đúng lúc đổi. Đó là điều Level 2 phải sửa.</p>"},{"id":"s46","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Nguyên tắc: <b>tay phải là dòng chảy</b> — không dừng, không chậm lại vì tay trái đang bận đổi. Kể cả khi tay trái chưa kịp bấm sạch, tay phải vẫn quạt đúng nhịp. Giữ nhịp trước, tiếng sạch sau.</p>"},{"id":"s47","order":3,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Miệng đếm chính là “dây an toàn” của nhịp. Khi tay trái đổi, nếu miệng vẫn đếm 1–2–3–4 đều, tay phải sẽ bám theo tiếng đếm mà không khựng.</p>"},{"id":"s48","order":4,"logic":"LAM","type":"guitar_metronome","title":"Metronome","interactive":{"tempo":70,"beatsPerBar":4,"caption":"⑤ Metronome bật liên tục. Quạt đều + đổi + miệng đếm to; giữ 8 ô nhịp có điểm đổi, không hụt phách nào."}},{"id":"s49","order":5,"logic":"LAM","type":"guitar_strumscore","title":"Strum Score","interactive":{"chords":["Am","C","Am","C"],"beatsPerBar":4,"tempo":60,"freqsList":[[110,164.81,220,261.63,329.63],[130.81,164.81,196,261.63,329.63],[110,164.81,220,261.63,329.63],[130.81,164.81,196,261.63,329.63]],"caption":"Quạt đều theo ô sáng, đổi hợp âm đúng phách 1 mỗi ô — chú ý KHÔNG khựng tay phải ở điểm đổi."}},{"id":"s50","order":6,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Tay phải quạt nốt đen đều xuyên qua điểm đổi Am↔C, không khựng, không đổi tốc độ; miệng vẫn đếm.</b></div></div>"}]$json$::jsonb);

  -- Bài 2.4 — Tai kiểm soát: dây 1 và bass  (dh24)
  v_les := 'd1c00204-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 2.4 — Tai kiểm soát: dây 1 và bass', 'flow', 3, 'free', '[]'::jsonb, 'qr:dh24')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 3, content_url = 'qr:dh24';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 2.4 — Tai kiểm soát: dây 1 và bass', 20, 'published', $json$[{"id":"s51","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Đổi Am ↔ C và tự hỏi: có phải MỌI thứ đều đổi không? Nghe kỹ, có thứ đổi và có thứ giữ nguyên.</p>"},{"id":"s52","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Hai điểm neo: <b>dây 1 (Mi) GIỮ NGUYÊN</b> ở cả Am và C — mỏ neo soát tay phải. <b>Bass ĐỔI: La (Am) → Đô (C)</b> — chỗ nghe “hợp âm đã sang chưa”.</p>"},{"id":"s53","order":3,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Nghe chủ động ở Level 2 là biết cái gì phải đều (dây 1) và cái gì phải đổi (bass). Nghe được cả hai, không cần nhìn tay cũng biết đổi đúng hay chưa.</p>"},{"id":"s54","order":4,"logic":"LAM","type":"guitar_ear","title":"④ Nghe & đoán: dây 1 (giữ) hay bass (đổi)?","interactive":{"pool":[1,5],"rounds":6,"passScore":4}},{"id":"s55","order":5,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Khi đổi Am↔C, nghe được dây 1 giữ đều và bass đổi La→Đô, nghe ra sự thay đổi màu hoà âm — không nhìn tay.</b></div></div>"}]$json$::jsonb);

  -- Bài 2.5 — Tai sửa tay  (dh25)
  v_les := 'd1c00205-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 2.5 — Tai sửa tay', 'flow', 4, 'free', '[]'::jsonb, 'qr:dh25')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 4, content_url = 'qr:dh25';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 2.5 — Tai sửa tay', 20, 'published', $json$[{"id":"s56","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Lần này, khi đổi bị lỗi, đừng vội nhìn tay. Nhắm mắt và hỏi: lỗi này nghe ra ở đâu?</p>"},{"id":"s57","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Tai chỉ ra lỗi ở tay nào. <b>Âm cao / dây 1 hụt, mất, không đều → lỗi TAY PHẢI</b> (quạt không tới, khựng). <b>Bass đổi đúng lúc nhưng tiếng đứt / rè → lỗi TAY TRÁI</b> (cách chuyển ngón, bấm chưa kịp sạch).</p>"},{"id":"s58","order":3,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Đây là lúc tai trở thành bộ phận kiểm tra kỹ thuật. Thay vì đoán mò rồi sửa lung tung, bạn nghe ra lỗi ở đâu rồi chỉ sửa đúng chỗ đó.</p>"},{"id":"s59","order":4,"logic":"LAM","type":"guitar_listen","title":"Nghe & chọn","interactive":{"question":"Khi đổi hợp âm, nếu ÂM CAO (dây 1) bỗng hụt hoặc không đều — lỗi thường ở tay nào?","plays":[{"label":"Nghe đổi Am → C","chords":[[110,164.81,220,261.63,329.63],[130.81,164.81,196,261.63,329.63]]}],"options":["Tay phải (quạt không tới, hoặc khựng)","Tay trái (bấm chưa kịp sạch)"],"answer":0,"explain":"Dây 1 do tay phải quạt tới. Nếu bass đổi đúng lúc mà tiếng vẫn đứt/rè thì mới là lỗi tay trái. Tai chỉ đúng chỗ để sửa."}},{"id":"s60","order":5,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Chỉ bằng cách nghe, đoán đúng lỗi đang ở tay phải hay tay trái, và sửa trúng chỗ.</b></div></div>"}]$json$::jsonb);

  -- Bài 2.6 — Ghép Am ↔ C, rồi mở rộng cặp  (dh26)
  v_les := 'd1c00206-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 2.6 — Ghép Am ↔ C, rồi mở rộng cặp', 'flow', 5, 'free', '[]'::jsonb, 'qr:dh26')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 5, content_url = 'qr:dh26';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 2.6 — Ghép Am ↔ C, rồi mở rộng cặp', 30, 'published', $json$[{"id":"s61","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Chạy vòng |Am |C |Am |C | với đầy đủ: quạt đều, đếm, nghe dây 1 và bass. Ghép từng lớp.</p>"},{"id":"s62","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Khi Am↔C đã mượt, tư duy vừa xây (ngón trụ · chuẩn bị trước · hai điểm neo) mang thẳng sang các cặp khác: <b>C↔Fmaj7, C↔Dm, Am↔Dm</b> (bass vẫn ở dây 5/dây 4).</p>"},{"id":"s63","order":3,"logic":"NHAN","type":"guitar_chord","title":"Hợp âm Dm","interactive":{"name":"Dm","frets":[-1,-1,0,2,3,1],"freqs":[0,0,146.83,220,293.66,349.23],"caption":"Dm (Rê thứ) — bass ở dây 4. Bấm <b>Nghe</b> rồi gảy thử trên đàn."}},{"id":"s64","order":4,"logic":"NHAN","type":"guitar_chord","title":"Hợp âm Fmaj7","interactive":{"name":"Fmaj7","frets":[-1,-1,3,2,1,0],"freqs":[0,0,174.61,220,261.63,329.63],"caption":"Fmaj7 — bass ở dây 4; giữ ngón 1 làm điểm tựa với C. Bấm <b>Nghe</b> rồi gảy thử trên đàn."}},{"id":"s65","order":5,"logic":"LAM","type":"guitar_metronome","title":"Metronome","interactive":{"tempo":70,"beatsPerBar":4,"caption":"⑤ Backing/metronome: chạy Am–C tới khi 8 lần đổi liên tục không vỡ nhịp, rồi áp cùng cách sang C–Fmaj7, C–Dm, Am–Dm."}},{"id":"s66","order":6,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Đổi qua lại hai hợp âm, giữ nhịp liên tục, tay phải không khựng, tai nghe được dây 1 và bass — với Am↔C và ít nhất một cặp mở rộng.</b></div></div>"}]$json$::jsonb);

  -- Bài 2.7 — Bắt đầu từ dây bass (chặn ngón cái)  (dh27)
  v_les := 'd1c00207-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 2.7 — Bắt đầu từ dây bass (chặn ngón cái)', 'flow', 6, 'free', '[]'::jsonb, 'qr:dh27')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 6, content_url = 'qr:dh27';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 2.7 — Bắt đầu từ dây bass (chặn ngón cái)', 30, 'published', $json$[{"id":"s67","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Bấm E và quạt cả 6 dây — nghe tiếng trầm mới, sâu hơn Am/C. Rồi bấm C mà quạt cả 6 dây: dây 6 lọt vào làm hợp âm nghe đục. Vậy mỗi hợp âm cần bắt đầu quạt từ một dây khác nhau.</p>"},{"id":"s68","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Mỗi hợp âm có một <b>dây bass</b> — bắt đầu quạt từ đúng dây đó. Am, C bass ở dây 5 → không để dây 6 kêu. E, G, G7 bass ở dây 6 → quạt cả 6 dây.</p>"},{"id":"s69","order":3,"logic":"NHAN","type":"guitar_chord","title":"Hợp âm E","interactive":{"name":"E","frets":[0,2,2,1,0,0],"freqs":[82.41,123.47,164.81,207.65,246.94,329.63],"caption":"E (Mi trưởng) — bass ở dây 6, quạt đủ 6 dây. Bấm <b>Nghe</b> rồi gảy thử trên đàn."}},{"id":"s70","order":4,"logic":"NHAN","type":"guitar_chord","title":"Hợp âm G","interactive":{"name":"G","frets":[3,2,0,0,0,3],"freqs":[98,123.47,146.83,196,246.94,392],"caption":"G (Sol trưởng) — bass ở dây 6, quạt đủ 6 dây. Bấm <b>Nghe</b> rồi gảy thử trên đàn."}},{"id":"s71","order":5,"logic":"NHAN","type":"guitar_chord","title":"Hợp âm G7","interactive":{"name":"G7","frets":[3,2,0,0,0,1],"freqs":[98,123.47,146.83,196,246.94,349.23],"caption":"G7 — bass ở dây 6, quạt đủ 6 dây. Bấm <b>Nghe</b> rồi gảy thử trên đàn."}},{"id":"s72","order":6,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<div style='background:#FBF6ED; border-left:4px solid #BF5A37; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#BF5A37; margin-bottom:6px;'>Chặn bằng ngón cái</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'>Với hợp âm bass ở dây 5 (Am, C), vắt ngón cái qua đầu cần đàn, chạm nhẹ dây 6 cho nó câm. Ngón cái không bấm phím — chỉ “đậu” lên dây 6. Nhờ vậy tay phải cứ quạt cả 6 dây mà dây 6 vẫn im.</div></div>"},{"id":"s73","order":7,"logic":"NHAN","type":"text","title":"④ Nghe","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>🎧 Trên App</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'>Nghe C quạt cả 6 dây (đục) và C chặn dây 6 (gọn); nghe Am → E bass “rơi xuống” dây 6. Có <b>video hướng dẫn mẫu</b> chặn ngón cái (thumb-mute).</div></div>"},{"id":"s74","order":8,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Quạt Am/C mà dây 6 im (nhờ ngón cái), quạt E/G/G7 đủ 6 dây bass rõ, và chỉnh được phạm vi quạt khi đổi qua lại.</b></div></div>"}]$json$::jsonb);

  -- Bài 2.8 — Ba cặp có bass dây 6  (dh28)
  v_les := 'd1c00208-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 2.8 — Ba cặp có bass dây 6', 'flow', 7, 'free', '[]'::jsonb, 'qr:dh28')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 7, content_url = 'qr:dh28';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 2.8 — Ba cặp có bass dây 6', 30, 'published', $json$[{"id":"s75","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Mang mọi thứ đã học — ngón trụ, chuẩn bị trước, tay phải đều, hai điểm neo — vào ba cặp mới. Việc mới duy nhất là chỉnh phạm vi quạt khi đổi giữa dây 5 và dây 6.</p>"},{"id":"s76","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'><b>Am↔E</b>: gần cùng thế bấm, dời một dây; bass La(d5)→Mi(d6), dây 1 giữ. <b>C↔G7</b>: bass Đô(d5)→Sol(d6). <b>C↔G</b>: xa nhất, bass Đô→Sol và cả dây 1 đổi (Mi→Sol) — để cuối.</p>"},{"id":"s77","order":3,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Điểm mới duy nhất: sang hợp âm dây 6 thì mở phạm vi quạt xuống dây 6; về hợp âm dây 5 thì ngón cái chặn lại. Tư duy ngón trụ và chuẩn bị vẫn y như cũ.</p>"},{"id":"s78","order":4,"logic":"LAM","type":"guitar_backing","title":"Nhạc nền","interactive":{"chords":["Am","E","C","G","C","G7"],"tempo":64,"beatsPerBar":4,"freqsList":[[110,164.81,220,261.63,329.63],[82.41,123.47,164.81,207.65,246.94,329.63],[130.81,164.81,196,261.63,329.63],[98,123.47,146.83,196,246.94,392],[130.81,164.81,196,261.63,329.63],[98,123.47,146.83,196,246.94,349.23]],"caption":"Bật nền các cặp có bass dây 6. Nghe bass “nhảy” giữa dây 5 và dây 6; quạt theo và chỉnh phạm vi quạt cho khớp."}},{"id":"s79","order":5,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Đổi được cả ba cặp bass dây 6 mà nhịp không vỡ, phạm vi quạt đổi đúng, tai nghe được bass nhảy dây.</b></div></div>"}]$json$::jsonb);

  -- Tự kiểm Level 2  (dh2check)
  v_les := 'd1c00299-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Tự kiểm Level 2', 'flow', 8, 'free', '[]'::jsonb, 'qr:dh2check')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 8, content_url = 'qr:dh2check';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Tự kiểm Level 2', 20, 'published', $json$[{"id":"s80","order":1,"logic":"DAN","type":"text","title":"Tự kiểm","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Đánh dấu khi bạn làm được</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'>Chỗ nào chưa đạt, quay lại đúng bài rèn năng lực đó. Khi cả bảng đều đạt, bạn sẵn sàng cho Level tiếp theo.</div></div>"},{"id":"s81","order":2,"logic":"NGAM","type":"checklist","title":"Bảng tự kiểm","interactive":{"items":["Đổi Am↔C mà tay phải không khựng","Hợp âm mới vào đúng phách 1 (chuẩn bị từ sau phách 4)","Vẫn đếm 1–2–3–4 xuyên điểm đổi","Nghe dây 1 (Mi) đều và bass (La→Đô) đổi","Chỉ nghe, đoán được lỗi ở tay phải hay tay trái","Nghe ra sự thay đổi màu hoà âm Am→C","Tận dụng ngón trụ (ngón 1&2 giữ, chỉ ngón 3 di)","Bấm vừa đủ lực, tay không đau khi luyện lâu","Quạt được cặp bass dây 6 (Am–E, C–G7…), chỉnh phạm vi quạt"]}}]$json$::jsonb);

  -- ===== Level 3: Vòng hoà âm · Biết mình đang ở đâu =====
  -- Tái dùng module "Vòng hoà âm" đã có (giữ nguyên 8 bài strum bên dưới).
  v_mod := '319654a9-f926-4b68-8adb-d5a1f566718d';
  UPDATE edu_modules SET name = 'Level 3: Vòng hoà âm · Biết mình đang ở đâu', order_index = 3 WHERE id = v_mod;

  -- Bài 3.0 — Ôn dây 6 & hợp âm mới E7  (dh30)
  v_les := 'd1c00300-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 3.0 — Ôn dây 6 & hợp âm mới E7', 'flow', 0, 'free', '[]'::jsonb, 'qr:dh30')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 0, content_url = 'qr:dh30';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 3.0 — Ôn dây 6 & hợp âm mới E7', 20, 'published', $json$[{"id":"s82","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Nhớ lại Bài 2.7: hợp âm bass ở dây 5 (Am, C) thì chặn dây 6 bằng ngón cái; bass ở dây 6 thì quạt đủ 6 dây. Level 3 dùng nhiều hợp âm dây 6 hơn — và một hợp âm mới: E7.</p>"},{"id":"s83","order":2,"logic":"NHAN","type":"guitar_chord","title":"Hợp âm E7","interactive":{"name":"E7","frets":[0,2,0,1,0,0],"freqs":[82.41,123.47,146.83,207.65,246.94,329.63],"caption":"E7 — bass ở dây 6 (Mi trầm), quạt đủ 6 dây. Bấm <b>Nghe</b> rồi gảy thử trên đàn."}},{"id":"s84","order":3,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Trong một vòng, hợp âm bass dây 5/4 (C, Am, Dm) và bass dây 6 (G, G7, E7) đứng xen nhau, nên phạm vi quạt đổi liên tục. Ngón cái chặn dây 6 giúp quạt “một mạch” mà không phải né.</p>"},{"id":"s85","order":4,"logic":"NHAN","type":"text","title":"④ Nghe","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>🎧 Trên App</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'>Nghe E7 và so với E; nghe bass dây 6 “xuống sâu”. Có <b>video hướng dẫn mẫu</b> phạm vi quạt dây 6.</div></div>"},{"id":"s86","order":5,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Bấm E7 rõ, quạt đủ 6 dây; khi xen hợp âm dây 5 với dây 6, chỉnh được phạm vi quạt đúng lúc.</b></div></div>"}]$json$::jsonb);

  -- Bài 3.1 — Ghép 4 hợp âm thành một vòng  (dh31)
  v_les := 'd1c00301-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 3.1 — Ghép 4 hợp âm thành một vòng', 'flow', 1, 'free', '[]'::jsonb, 'qr:dh31')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 1, content_url = 'qr:dh31';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 3.1 — Ghép 4 hợp âm thành một vòng', 20, 'published', $json$[{"id":"s87","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Đến giờ bạn đổi qua lại hai hợp âm. Bây giờ đi một chuỗi bốn hợp âm rồi quay lại đầu — đó là một “vòng”. Ví dụ xuyên suốt: C → Am → Dm → G7 → (về) C.</p>"},{"id":"s88","order":2,"logic":"NHAN","type":"guitar_chord","title":"Hợp âm C","interactive":{"name":"C","frets":[-1,3,2,0,1,0],"freqs":[0,130.81,164.81,196,261.63,329.63],"caption":"C (Đô trưởng) — bass ở dây 5. Ngón 1 dây 2/f1, ngón 2 dây 4/f2, ngón 3 dây 5/f3. Bấm <b>Nghe</b> rồi gảy thử trên đàn."}},{"id":"s89","order":3,"logic":"NHAN","type":"guitar_chord","title":"Hợp âm Am","interactive":{"name":"Am","frets":[-1,0,2,2,1,0],"freqs":[0,110,164.81,220,261.63,329.63],"caption":"Am (La thứ) — bass ở dây 5. Ngón 1 dây 2/f1, ngón 2 dây 4/f2, ngón 3 dây 3/f2. Bấm <b>Nghe</b> rồi gảy thử trên đàn."}},{"id":"s90","order":4,"logic":"NHAN","type":"guitar_chord","title":"Hợp âm Dm","interactive":{"name":"Dm","frets":[-1,-1,0,2,3,1],"freqs":[0,0,146.83,220,293.66,349.23],"caption":"Dm (Rê thứ) — bass ở dây 4. Bấm <b>Nghe</b> rồi gảy thử trên đàn."}},{"id":"s91","order":5,"logic":"NHAN","type":"guitar_chord","title":"Hợp âm G7","interactive":{"name":"G7","frets":[3,2,0,0,0,1],"freqs":[98,123.47,146.83,196,246.94,349.23],"caption":"G7 — bass ở dây 6, quạt đủ 6 dây. Bấm <b>Nghe</b> rồi gảy thử trên đàn."}},{"id":"s92","order":6,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Hết hợp âm thứ tư (G7) thì quay lại hợp âm thứ nhất (C) — gọi là “khép vòng”. Vòng cứ thế lặp mãi. Nhiệm vụ đầu tiên: đi trọn vòng mà tay phải vẫn đều.</p>"},{"id":"s93","order":7,"logic":"LAM","type":"guitar_metronome","title":"Metronome","interactive":{"tempo":70,"beatsPerBar":4,"caption":"⑤ Đi hết vòng thật chậm: mỗi hợp âm một ô nhịp (4 phách), quạt đều, đếm 1–2–3–4. C/Am/Dm chặn dây 6; G7 quạt đủ 6 dây. Khép về C rồi đi tiếp."}},{"id":"s94","order":8,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Đi trọn vòng C–Am–Dm–G7 rồi khép về C, lặp được vài vòng, tay phải đều và không đứt.</b></div></div>"}]$json$::jsonb);

  -- Bài 3.2 — Giữ dòng chảy: chuẩn bị liên tục  (dh32)
  v_les := 'd1c00302-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 3.2 — Giữ dòng chảy: chuẩn bị liên tục', 'flow', 2, 'free', '[]'::jsonb, 'qr:dh32')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 2, content_url = 'qr:dh32';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 3.2 — Giữ dòng chảy: chuẩn bị liên tục', 20, 'published', $json$[{"id":"s95","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Trong một vòng, vừa xong hợp âm này thì đã phải nghĩ tới hợp âm kế — không lúc nào được “nghỉ tay”.</p>"},{"id":"s96","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>“Không reset”: tay trái đừng buông hẳn rồi mới đi tìm hợp âm kế. Vòng có bốn mối nối (C→Am, Am→Dm, Dm→G7, G7→C), mỗi mối nối chuẩn bị sau phách 4 — nay là một chuỗi liên tục.</p>"},{"id":"s97","order":3,"logic":"LAM","type":"guitar_metronome","title":"Metronome","interactive":{"tempo":70,"beatsPerBar":4,"caption":"⑤ Metronome liên tục; mỗi mối nối chuẩn bị ngay sau phách 4. Mối nối nào yếu → tách luyện riêng như một cặp rồi ghép lại."}},{"id":"s98","order":4,"logic":"LAM","type":"guitar_strumscore","title":"Strum Score","interactive":{"chords":["C","Am","Dm","G7"],"beatsPerBar":4,"tempo":66,"freqsList":[[130.81,164.81,196,261.63,329.63],[110,164.81,220,261.63,329.63],[146.83,220,293.66,349.23],[98,123.47,146.83,196,246.94,349.23]],"caption":"Ô phách sáng chạy quanh vòng, phách 1 mỗi ô tự đổi hợp âm. Quạt đều, chuẩn bị hợp âm kế ngay sau phách 4 — không để “khoảng chết” ở mối nối."}},{"id":"s99","order":5,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Lặp vòng nhiều lần liên tục, mỗi hợp âm mới vào đúng phách 1, không còn “khoảng chết” ở mối nối nào.</b></div></div>"}]$json$::jsonb);

  -- Bài 3.3 — Biết mình đang ở đâu  (dh33)
  v_les := 'd1c00303-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 3.3 — Biết mình đang ở đâu', 'flow', 3, 'free', '[]'::jsonb, 'qr:dh33')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 3, content_url = 'qr:dh33';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 3.3 — Biết mình đang ở đâu', 20, 'published', $json$[{"id":"s100","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Khi lặp vòng nhiều lần, rất dễ “trôi” — đang chơi mà không biết mình đang ở hợp âm thứ mấy.</p>"},{"id":"s101","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Đánh số vị trí trong vòng: C là 1, Am là 2, Dm là 3, G7 là 4. Lúc nào cũng biết mình đang ở vị trí nào và hợp âm nào sẽ đến tiếp.</p>"},{"id":"s102","order":3,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Nhớ vị trí không phải đọc thuộc tên bốn hợp âm, mà là cảm được “đang ở đoạn nào của vòng” và hợp âm kế sắp tới — để tay chuẩn bị trước.</p>"},{"id":"s103","order":4,"logic":"LAM","type":"guitar_listen","title":"Nghe & chọn","interactive":{"question":"Trong vòng C–Am–Dm–G7, ngay sau Dm là hợp âm nào?","plays":[{"label":"Nghe vòng","chords":[[130.81,164.81,196,261.63,329.63],[110,164.81,220,261.63,329.63],[146.83,220,293.66,349.23],[98,123.47,146.83,196,246.94,349.23]]}],"options":["G7","C","Am","Dm"],"answer":0,"explain":"Thứ tự vòng: C → Am → Dm → G7 → (về) C. Luôn biết mình đang ở đâu và hợp âm kế là gì để tay chuẩn bị trước."}},{"id":"s104","order":5,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Bất cứ lúc nào cũng nói được mình đang ở hợp âm thứ mấy và hợp âm tiếp theo là gì.</b></div></div>"}]$json$::jsonb);

  -- Bài 3.4 — Đi và về: hợp âm chủ  (dh34)
  v_les := 'd1c00304-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 3.4 — Đi và về: hợp âm chủ', 'flow', 4, 'free', '[]'::jsonb, 'qr:dh34')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 4, content_url = 'qr:dh34';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 3.4 — Đi và về: hợp âm chủ', 20, 'published', $json$[{"id":"s105","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Lặp vòng và để ý: có một hợp âm nghe như “đặt chân về nhà” — yên ổn hơn các hợp âm khác.</p>"},{"id":"s106","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Trong vòng C–Am–Dm–G7, hợp âm đó là <b>C</b>. G7 tạo cảm giác “đang chờ, chưa xong”, rồi về C là “xong, ổn rồi”. Bass đi Đô → La → Rê → Sol, rồi Sol (G7) kéo về Đô (C).</p>"},{"id":"s107","order":3,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Bạn không cần định nghĩa lý thuyết. Cứ nghe: chỗ nào làm bạn thấy “kết thúc, ổn” — đó là hợp âm chủ, điểm về nhà của vòng.</p>"},{"id":"s108","order":4,"logic":"LAM","type":"guitar_listen","title":"Nghe & chọn","interactive":{"question":"Nghe vòng C–Am–Dm–G7. Hợp âm nào cho cảm giác “kết, đã về nhà”?","plays":[{"label":"Nghe vòng","chords":[[130.81,164.81,196,261.63,329.63],[110,164.81,220,261.63,329.63],[146.83,220,293.66,349.23],[98,123.47,146.83,196,246.94,349.23]]}],"options":["C","Am","Dm","G7"],"answer":0,"explain":"G7 tạo cảm giác “đang chờ”, rồi về C là “xong, ổn”. C là hợp âm chủ — điểm về nhà của vòng này."}},{"id":"s109","order":5,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Chỉ ra được điểm “về nhà” của vòng bằng tai, và cảm được G7 “kéo” về C.</b></div></div>"}]$json$::jsonb);

  -- Bài 3.5 — Hát ầm ừ trong vòng  (dh35)
  v_les := 'd1c00305-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 3.5 — Hát ầm ừ trong vòng', 'flow', 5, 'free', '[]'::jsonb, 'qr:dh35')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 5, content_url = 'qr:dh35';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 3.5 — Hát ầm ừ trong vòng', 20, 'published', $json$[{"id":"s110","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Giữ vòng chạy bằng tay, rồi đưa giọng vào — chưa hát ca khúc có lời, chỉ ngân “ầm ừ” như tiếng “ừm” ở Level 1.</p>"},{"id":"s111","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Ngân một âm hợp với hợp âm đang vang, và đổi âm khi vòng đổi hợp âm. Ở hợp âm chủ (C), giọng dễ “về” nhất — lấy đó làm điểm tựa.</p>"},{"id":"s112","order":3,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Tay giữ dòng chảy, giọng “ầm ừ” đi trên dòng chảy đó. Mục tiêu là giọng hoà vào vòng, chưa phải hát đúng lời (để dành Level 5). Nếu phải chọn, giữ nhịp trước.</p>"},{"id":"s113","order":4,"logic":"LAM","type":"guitar_backing","title":"Nhạc nền","interactive":{"chords":["C","Am","Dm","G7"],"tempo":68,"beatsPerBar":4,"freqsList":[[130.81,164.81,196,261.63,329.63],[110,164.81,220,261.63,329.63],[146.83,220,293.66,349.23],[98,123.47,146.83,196,246.94,349.23]],"caption":"Bật nền vòng rồi ngân “ầm ừ” bám theo. Nghe âm của mình có hợp với hợp âm đang vang không; mỗi khi vòng về C, ngân về âm hợp âm chủ."}},{"id":"s114","order":5,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Vừa giữ vòng vừa ngân “ầm ừ” khớp với hợp âm đang vang, tay phải không khựng.</b></div></div>"}]$json$::jsonb);

  -- Bài 3.6 — Lạc & tìm lại  (dh36)
  v_les := 'd1c00306-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 3.6 — Lạc & tìm lại', 'flow', 6, 'free', '[]'::jsonb, 'qr:dh36')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 6, content_url = 'qr:dh36';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 3.6 — Lạc & tìm lại', 20, 'published', $json$[{"id":"s115","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Khi vừa đàn vừa ngân, rất dễ lạc: hoặc sai vị trí hợp âm (lạc vòng), hoặc giọng trôi cao độ (lạc cao độ).</p>"},{"id":"s116","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<div style='background:#FBF6ED; border-left:4px solid #BF5A37; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#BF5A37; margin-bottom:6px;'>Hai kiểu lạc</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'>• <b>Lạc vòng</b>: tay chơi sai vị trí, hợp âm không khớp chỗ đang ở.<br>• <b>Lạc cao độ</b>: giọng trôi lên/xuống, không còn khớp hợp âm.<br><br>Cách tìm lại: đừng dừng. Dùng tiếng đàn đang chạy — bass hoặc hợp âm chủ — làm mốc, chờ tới điểm “về nhà” rồi vào lại cho đúng.</div></div>"},{"id":"s117","order":3,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Người mới lạc thì dừng hẳn. Người điều khiển vòng thì giữ tay chạy, chỉ đưa giọng và vị trí về đúng chỗ — thường là ở hợp âm chủ.</p>"},{"id":"s118","order":4,"logic":"LAM","type":"guitar_listen","title":"Nghe & chọn","interactive":{"question":"Đang đàn mà bị lạc vòng — nên làm gì?","options":["Dừng hẳn, dò lại từ đầu","Giữ tay chạy đều, chờ tới hợp âm chủ rồi vào lại","Bỏ, chơi bài khác"],"answer":1,"explain":"Người điều khiển vòng không dừng: dùng tiếng đàn đang chạy (bass, hợp âm chủ) làm mốc, chờ điểm “về nhà” rồi vào lại đúng chỗ."}},{"id":"s119","order":5,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Khi lạc, bạn không dừng — dùng tiếng đàn đang chạy để tìm lại điểm đứng và vào lại vòng.</b></div></div>"}]$json$::jsonb);

  -- Bài 3.7 — Điều khiển một vòng (Capstone)  (dh37)
  v_les := 'd1c00307-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 3.7 — Điều khiển một vòng (Capstone)', 'flow', 7, 'free', '[]'::jsonb, 'qr:dh37')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 7, content_url = 'qr:dh37';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 3.7 — Điều khiển một vòng (Capstone)', 40, 'published', $json$[{"id":"s120","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Giờ làm tất cả cùng lúc trên một vòng, lặp như một bản loop không dứt.</p>"},{"id":"s121","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Quy trình: chọn vòng → giữ nhịp → khép vòng đều → biết mình đang ở đâu → cảm hợp âm chủ → hát khớp → nếu lạc thì tự tìm lại.</p>"},{"id":"s122","order":3,"logic":"LAM","type":"guitar_metronome","title":"Metronome","interactive":{"tempo":70,"beatsPerBar":4,"caption":"⑤ Chạy vòng C–Am–Dm–G7 như loop nhiều vòng liên tục, có ngân ầm ừ. Khi vững, thử một vòng khác (vd Am–Dm–E7–Am về Am) để kiểm tra chuyển năng lực."}},{"id":"s123","order":4,"logic":"DAN","type":"text","title":"Luyện thêm","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Các bài \"Tập vòng\" bên dưới</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'>Ngay trong Level này có các bài <b>Tập vòng</b> trên nền trống–bass (Strum Score) cho cả 5 vòng hoà âm — dùng để luyện tay cho tới khi loop mượt.</div></div>"},{"id":"s124","order":5,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Đàn một vòng → lặp liên tục → giữ nhịp → ngân “ầm ừ” khớp → tự nhận ra khi lạc → tự tìm lại → cảm nhận hợp âm chủ.</b></div></div>"}]$json$::jsonb);

  -- Tự kiểm Level 3  (dh3check)
  v_les := 'd1c00399-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Tự kiểm Level 3', 'flow', 8, 'free', '[]'::jsonb, 'qr:dh3check')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 8, content_url = 'qr:dh3check';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Tự kiểm Level 3', 20, 'published', $json$[{"id":"s125","order":1,"logic":"DAN","type":"text","title":"Tự kiểm","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Đánh dấu khi bạn làm được</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'>Chỗ nào chưa đạt, quay lại đúng bài rèn năng lực đó. Khi cả bảng đều đạt, bạn sẵn sàng cho Level tiếp theo.</div></div>"},{"id":"s126","order":2,"logic":"NGAM","type":"checklist","title":"Bảng tự kiểm","interactive":{"items":["Quạt đều trọn một vòng 4 hợp âm","Giữ nhịp & đếm qua nhiều lần lặp vòng","Chuẩn bị hợp âm kế trước phách đổi (mọi mối nối)","Nghe được sự thay đổi liên tục của vòng","Nói được đang ở hợp âm thứ mấy","Đoán được hợp âm tiếp theo","Chỉ ra được hợp âm chủ (điểm “về nhà”)","Ngân “ầm ừ” khớp với vòng","Nhận ra khi mình lạc & dùng tiếng đàn tìm lại"]}}]$json$::jsonb);

  -- Đẩy 8 bài strum "Tập vòng" cũ xuống sau các bài flow 3.x (giữ nguyên nội dung & id).
  -- Chỉ đẩy khi còn ở đầu (idempotent — chạy lại không cộng dồn).
  UPDATE edu_course_lessons SET order_index = order_index + 20 WHERE module_id = v_mod AND lesson_type IN ('strum','native') AND order_index < 20;

  -- ===== Level 4: Nhịp và phách =====
  SELECT id INTO v_mod FROM edu_modules WHERE course_id = v_course AND name ILIKE 'Level 4%' LIMIT 1;
  IF v_mod IS NULL THEN
    INSERT INTO edu_modules (course_id, name, order_index) VALUES (v_course, 'Level 4: Nhịp và phách', 4) RETURNING id INTO v_mod;
  ELSE
    UPDATE edu_modules SET name = 'Level 4: Nhịp và phách', order_index = 4 WHERE id = v_mod;
  END IF;

  -- Bài 4.1 — Ba loại nhịp: 2/4 · 3/4 · 4/4  (dh41)
  v_les := 'd1c00401-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 4.1 — Ba loại nhịp: 2/4 · 3/4 · 4/4', 'flow', 0, 'free', '[]'::jsonb, 'qr:dh41')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 0, content_url = 'qr:dh41';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 4.1 — Ba loại nhịp: 2/4 · 3/4 · 4/4', 20, 'published', $json$[{"id":"s127","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Đếm 1–2, rồi 1–2–3, rồi 1–2–3–4. Mỗi kiểu đếm là một loại nhịp — số phách trong mỗi ô khác nhau.</p>"},{"id":"s128","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'><b>2/4</b> có 2 phách mỗi ô, <b>3/4</b> có 3 phách, <b>4/4</b> có 4 phách. Quạt xuống một cái mỗi phách; phách 1 là phách mạnh.</p>"},{"id":"s129","order":3,"logic":"LAM","type":"guitar_metronome","title":"Metronome","interactive":{"tempo":70,"beatsPerBar":4,"caption":"④⑤ Chọn nhịp trên metronome (2/4, 3/4, 4/4). Nghe mỗi ô có mấy tiếng click trước khi quay lại phách 1. Quạt + đếm, giữ đều 8 ô mỗi loại nhịp."}},{"id":"s130","order":4,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Quạt đều và đếm đúng số phách trong cả 2/4, 3/4 và 4/4, khớp metronome.</b></div></div>"}]$json$::jsonb);

  -- Bài 4.2 — Phách mạnh, phách nhẹ  (dh42)
  v_les := 'd1c00402-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 4.2 — Phách mạnh, phách nhẹ', 'flow', 1, 'free', '[]'::jsonb, 'qr:dh42')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 1, content_url = 'qr:dh42';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 4.2 — Phách mạnh, phách nhẹ', 20, 'published', $json$[{"id":"s131","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Quạt đều theo metronome và để ý: phách 1 nghe có “nặng” hơn các phách khác không? Đừng cố nhấn — chỉ lắng nghe.</p>"},{"id":"s132","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<div style='background:#FBF6ED; border-left:4px solid #BF5A37; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#BF5A37; margin-bottom:6px;'>Trọng âm mỗi nhịp</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'>2/4: <b>MẠNH</b> – nhẹ · 3/4: <b>MẠNH</b> – nhẹ – nhẹ · 4/4: <b>MẠNH</b> – nhẹ – vừa – nhẹ (phách 3 hơi nhấn). Trọng âm là một <b>cảm giác</b>, không phải luật “đập mạnh phách 1” — khi quạt đều cùng metronome, phách mạnh tự nổi lên; việc của bạn là nghe ra nó.</div></div>"},{"id":"s133","order":3,"logic":"LAM","type":"guitar_metronome","title":"Metronome","interactive":{"tempo":70,"beatsPerBar":4,"caption":"④ Metronome nhấn phách 1. Quạt đều, lắng nghe phách nào “nặng” hơn; rồi nhắm mắt nghe một đoạn có nhấn, đoán 2/4, 3/4 hay 4/4."}},{"id":"s134","order":4,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Nghe và tự cảm nhận được phách mạnh, và nhận ra loại nhịp qua trọng âm — không cần đếm.</b></div></div>"}]$json$::jsonb);

  -- Bài 4.3 — Hợp âm bắt đầu ở phách nào  (dh43)
  v_les := 'd1c00403-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 4.3 — Hợp âm bắt đầu ở phách nào', 'flow', 2, 'free', '[]'::jsonb, 'qr:dh43')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 2, content_url = 'qr:dh43';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 4.3 — Hợp âm bắt đầu ở phách nào', 20, 'published', $json$[{"id":"s135","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Khi đổi hợp âm, hợp âm mới bắt đầu vang ở phách nào? Ở bài này, mỗi ô một hợp âm, và hợp âm mới vào phách 1.</p>"},{"id":"s136","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Một hợp âm cho cả ô nhịp; đổi ở phách 1 của ô sau. Tay phải quạt đều bốn phách. Ví dụ: | C · · · | G7 · · · | — đổi đúng phách 1.</p>"},{"id":"s137","order":3,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Tay phải là dòng nhịp — không dừng vì đổi, nay đặt rõ trên khung phách. <b>Hợp âm đi theo phách.</b></p>"},{"id":"s138","order":4,"logic":"LAM","type":"guitar_metronome","title":"Metronome","interactive":{"tempo":70,"beatsPerBar":4,"caption":"⑤ Metronome 4/4. Tập | C · · · | G7 · · · | — đổi đúng phách 1, miệng đếm 1–2–3–4, hợp âm mới rơi đúng “1”."}},{"id":"s139","order":5,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Đổi hợp âm đúng phách 1, tay phải không dừng, miệng vẫn đếm.</b></div></div>"}]$json$::jsonb);

  -- Bài 4.4 — Hai hợp âm trong một ô nhịp  (dh44)
  v_les := 'd1c00404-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 4.4 — Hai hợp âm trong một ô nhịp', 'flow', 3, 'free', '[]'::jsonb, 'qr:dh44')
