  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 4.4 — Hai hợp âm trong một ô nhịp', 20, 'published', $json$[{"id":"s140","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Một ô nhịp có thể chứa hai hợp âm — hợp âm đổi ngay giữa ô, không chờ sang ô mới.</p>"},{"id":"s141","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Hai cách chia thường gặp trong 4/4: <b>| C · G7 · |</b> (C phách 1–2, G7 vào phách 3 — kiểu 2+2) và <b>| C · · G7 |</b> (C phách 1–3, G7 vào phách 4 — kiểu 3+1).</p>"},{"id":"s142","order":3,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Điểm đổi giờ không chỉ ở phách 1 mà ở giữa ô (phách 3 hoặc 4). Tay trái chuẩn bị ngón trước phách sẽ đổi; tay phải vẫn quạt đều.</p>"},{"id":"s143","order":4,"logic":"LAM","type":"guitar_metronome","title":"Metronome","interactive":{"tempo":70,"beatsPerBar":4,"caption":"⑤ Metronome 4/4. Tập | C · G7 · | (đổi phách 3) rồi | C · · G7 | (đổi phách 4). Khựng thì chỉ đếm và nói to phách sẽ đổi trước, rồi mới thêm tay trái."}},{"id":"s144","order":5,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Đổi hai hợp âm trong một ô đúng phách (3 hoặc 4), tay phải không dừng, miệng vẫn đếm.</b></div></div>"}]$json$::jsonb);

  -- Bài 4.5 — Ba hợp âm trong một ô nhịp  (dh45)
  v_les := 'd1c00405-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 4.5 — Ba hợp âm trong một ô nhịp', 'flow', 4, 'free', '[]'::jsonb, 'qr:dh45')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 4, content_url = 'qr:dh45';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 4.5 — Ba hợp âm trong một ô nhịp', 20, 'published', $json$[{"id":"s145","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Tăng thêm một bậc: ba hợp âm trong một ô. Dễ nhất là nhịp 3/4 — mỗi phách một hợp âm.</p>"},{"id":"s146","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Ví dụ 3/4: <b>| C G7 Am |</b> — mỗi phách một hợp âm. Rồi 4/4 vị trí KHÔNG đều: <b>| C · G7 Am |</b> — C phách 1–2, G7 phách 3, Am phách 4.</p>"},{"id":"s147","order":3,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Trong 4/4 không chia đều — bạn phải đọc điểm đổi theo phách, không chép mẫu. Đây là bậc khó hơn hai hợp âm/ô, nên tập vững Bài 4.4 trước.</p>"},{"id":"s148","order":4,"logic":"LAM","type":"guitar_metronome","title":"Metronome","interactive":{"tempo":70,"beatsPerBar":4,"caption":"⑤ Metronome. Tập 3/4 | C G7 Am | (đổi mỗi phách) rồi 4/4 | C · G7 Am | (đổi đúng phách 3 và 4), nhịp không vỡ."}},{"id":"s149","order":5,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Chơi được ba hợp âm trong một ô (3/4 và 4/4 vị trí không đều), đổi đúng phách, nhịp không vỡ.</b></div></div>"}]$json$::jsonb);

  -- Bài 4.6 — Nghe vị trí đổi trong dòng nhịp  (dh46)
  v_les := 'd1c00406-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 4.6 — Nghe vị trí đổi trong dòng nhịp', 'flow', 5, 'free', '[]'::jsonb, 'qr:dh46')
