  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 4.6 — Nghe vị trí đổi trong dòng nhịp', 20, 'published', $json$[{"id":"s150","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Đến giờ bạn đổi theo mẫu cho sẵn. Bây giờ nghe một đoạn CHƯA học và tự tìm: hợp âm đổi ở phách nào?</p>"},{"id":"s151","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Một bước chuyển lớn — từ “làm theo mẫu” sang “tự nghe và xác định”. Cách làm: vừa nghe vừa đếm phách, và đánh dấu phách nào có điểm đổi.</p>"},{"id":"s152","order":3,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Tai kết hợp với đếm: nghe màu hoà âm đổi + biết mình đang ở phách mấy = biết hợp âm đổi ở phách nào.</p>"},{"id":"s153","order":4,"logic":"LAM","type":"guitar_listen","title":"Nghe & chọn","interactive":{"question":"Nghe ô nhịp: C vang trước, rồi đổi sang G7. G7 đổi vào khoảng phách nào?","plays":[{"label":"Nghe ô nhịp (C… G7)","chords":[[130.81,164.81,196,261.63,329.63],[98,123.47,146.83,196,246.94,349.23]],"gap":1200}],"options":["Phách 1","Phách 2","Phách 3","Phách 4"],"answer":2,"explain":"C giữ phách 1–2, G7 vào phách 3 (chia 2+2). Vừa nghe vừa đếm 1–2–3–4 để bắt đúng điểm đổi."}},{"id":"s154","order":5,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Nghe một đoạn chưa học và xác định đúng hợp âm đổi ở phách nào.</b></div></div>"}]$json$::jsonb);

  -- Bài 4.7 — Đọc nhịp một đoạn mới (Capstone)  (dh47)
  v_les := 'd1c00407-0000-4000-8000-000000000000';
