    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 6, content_url = 'qr:dh47';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 4.7 — Đọc nhịp một đoạn mới (Capstone)', 40, 'published', $json$[{"id":"s155","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Gộp tất cả: nhận một đoạn nhạc mới và tự đọc nhịp của nó trước khi đàn.</p>"},{"id":"s156","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<div style='background:#FBF6ED; border-left:4px solid #BF5A37; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#BF5A37; margin-bottom:6px;'>Quy trình 5 bước</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'>1) Xác định nhịp — 2/4, 3/4 hay 4/4? 2) Đếm phách theo nhịp đó. 3) Xác định điểm đổi hợp âm — mỗi hợp âm bắt đầu ở phách nào? 4) Quạt đều theo phách. 5) Đổi hợp âm đúng phách, kể cả 2–3 hợp âm/ô.</div></div>"},{"id":"s157","order":3,"logic":"LAM","type":"guitar_metronome","title":"Metronome","interactive":{"tempo":70,"beatsPerBar":4,"caption":"⑤ Nhận một đoạn mới → chạy đủ 5 bước với metronome → đệm được đoạn đó."}},{"id":"s158","order":4,"logic":"LAM","type":"guitar_listen","title":"Nghe & chọn","interactive":{"question":"Nhận một đoạn nhạc MỚI để đệm — bước đầu tiên nên làm gì?","options":["Đàn luôn cho quen tay","Xác định nhịp (2/4·3/4·4/4) rồi đếm phách","Học thuộc lời trước"],"answer":1,"explain":"Quy trình: xác định nhịp → đếm phách → tìm điểm đổi hợp âm → quạt đều → đổi đúng phách. Nhìn nhịp trước, đàn sau."}},{"id":"s159","order":5,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Nhận đoạn mới → xác định nhịp → đếm phách → xác định điểm đổi → quạt đều → đổi đúng phách, kể cả 2–3 hợp âm/ô.</b></div></div>"}]$json$::jsonb);

  -- Tự kiểm Level 4  (dh4check)
  v_les := 'd1c00499-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Tự kiểm Level 4', 'flow', 7, 'free', '[]'::jsonb, 'qr:dh4check')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 7, content_url = 'qr:dh4check';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Tự kiểm Level 4', 20, 'published', $json$[{"id":"s160","order":1,"logic":"DAN","type":"text","title":"Tự kiểm","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Đánh dấu khi bạn làm được</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'>Chỗ nào chưa đạt, quay lại đúng bài rèn năng lực đó. Khi cả bảng đều đạt, bạn sẵn sàng cho Level tiếp theo.</div></div>"},{"id":"s161","order":2,"logic":"NGAM","type":"checklist","title":"Bảng tự kiểm","interactive":{"items":["Quạt đều trong 2/4, 3/4, 4/4","Vừa quạt vừa đếm phách","Giữ nhịp ổn định cùng metronome","Nghe & tự cảm nhận phách mạnh/nhẹ, nhận ra nhịp","Biết hợp âm bắt đầu ở phách nào","Xử lý 2 hợp âm/ô, đổi đúng phách","Xử lý 3 hợp âm/ô (3/4 và 4/4 vị trí không đều)","Đổi đúng phách mà tay phải không dừng","Nghe đoạn chưa học, xác định điểm đổi theo phách"]}}]$json$::jsonb);

  -- ===== Level 5: Tự chuẩn bị & đệm một bài hát mới =====
  SELECT id INTO v_mod FROM edu_modules WHERE course_id = v_course AND name ILIKE 'Level 5%' LIMIT 1;
  IF v_mod IS NULL THEN
    INSERT INTO edu_modules (course_id, name, order_index) VALUES (v_course, 'Level 5: Tự chuẩn bị & đệm một bài hát mới', 5) RETURNING id INTO v_mod;
  ELSE
    UPDATE edu_modules SET name = 'Level 5: Tự chuẩn bị & đệm một bài hát mới', order_index = 5 WHERE id = v_mod;
  END IF;

  -- Bài 5.1 — Tìm tông dễ chơi  (dh51)
  v_les := 'd1c00501-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 5.1 — Tìm tông dễ chơi', 'flow', 0, 'free', '[]'::jsonb, 'qr:dh51')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 0, content_url = 'qr:dh51';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 5.1 — Tìm tông dễ chơi', 20, 'published', $json$[{"id":"s162","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Bạn nhận một bài có sẵn hợp âm. Có thể trong đó có hợp âm khó (chặn, ngoài vốn của bạn). Việc đầu tiên: đưa bài về một tông dễ.</p>"},{"id":"s163","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Cùng một bài có thể chơi ở nhiều tông. Chọn tông mà bạn chỉ cần các hợp âm đã học — thường là <b>Am hoặc C</b>.</p>"},{"id":"s164","order":3,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Đưa về Am/C không làm đổi bài — chỉ đổi “chỗ đứng” để tay dễ chơi. Cao độ để hát sẽ chỉnh bằng capo ở bài sau.</p><div style='background:#F3E9F0; border-left:4px solid #9C4668; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#9C4668; margin-bottom:6px;'>Tôi muốn bạn nhớ</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'>Đích của Đệm hát 1 không phải thuộc tất cả hợp âm, mà là biết cách xử lý khi gặp một hợp âm chưa biết. Dịch tông + capo đưa bài về vốn đã học; gặp hợp âm lạ thì tra cứu (Bài 5.3).</div></div>"},{"id":"s165","order":4,"logic":"LAM","type":"guitar_listen","title":"Nghe & chọn","interactive":{"question":"Đưa một bài về tông Am hoặc C để làm gì?","plays":[{"label":"Nghe vòng tông C","chords":[[130.81,164.81,196,261.63,329.63],[110,164.81,220,261.63,329.63],[174.61,220,261.63,329.63],[98,123.47,146.83,196,246.94,349.23]]}],"options":["Cho bài hay hơn","Để chỉ cần dùng những hợp âm dễ đã học","Để hát cao hơn"],"answer":1,"explain":"Dịch tông không đổi bài — chỉ đổi “chỗ đứng” để tay bạn chỉ gặp hợp âm quen. Cao độ hát sẽ chỉnh riêng bằng capo."}},{"id":"s166","order":5,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Đưa được một bài về Am hoặc C, chỉ dùng những hợp âm bạn đã học.</b></div></div>"}]$json$::jsonb);

  -- Bài 5.2 — Capo để hát dễ hơn  (dh52)
  v_les := 'd1c00502-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 5.2 — Capo để hát dễ hơn', 'flow', 1, 'free', '[]'::jsonb, 'qr:dh52')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 1, content_url = 'qr:dh52';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 5.2 — Capo để hát dễ hơn', 20, 'published', $json$[{"id":"s167","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Tông C dễ chơi, nhưng có thể quá thấp hoặc quá cao so với giọng bạn. Đừng đổi hợp âm khó — hãy dùng capo.</p>"},{"id":"s168","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Capo là một thanh kẹp ngang cần đàn. Nó nâng cao độ của cả cây đàn lên, trong khi bạn vẫn bấm những thế hợp âm dễ như cũ.</p>"},{"id":"s169","order":3,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Không cần tính toán lý thuyết. Chỉ cần thử: kẹp capo ở vài ngăn, hát thử, và chọn chỗ giọng thấy thoải mái nhất.</p>"},{"id":"s170","order":4,"logic":"LAM","type":"guitar_listen","title":"Nghe & chọn","interactive":{"question":"Nghe cùng hợp âm C ở hai vị trí. Capo dùng để làm gì?","plays":[{"label":"C — không capo","chords":[[130.81,164.81,196,261.63,329.63]]},{"label":"C — như capo ngăn 2","chords":[[146.8292605393491,184.99297018186778,220.0025614686371,293.66974569918125,369.9971649842186]]}],"options":["Đổi sang hợp âm khó hơn","Nâng cao độ mà vẫn bấm thế dễ như cũ","Giúp chơi nhanh hơn"],"answer":1,"explain":"Capo nâng cao độ cả cây đàn; bạn vẫn bấm C, Am dễ như cũ. Thử vài ngăn, chọn chỗ hát thoải mái nhất. Có video hướng dẫn mẫu."}},{"id":"s171","order":5,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Chọn được vị trí capo hợp giọng — bằng cách thử và nghe, không cần tính lý thuyết.</b></div></div>"}]$json$::jsonb);

  -- Bài 5.3 — Biên soạn bảng hợp âm  (dh53)
  v_les := 'd1c00503-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 5.3 — Biên soạn bảng hợp âm', 'flow', 2, 'free', '[]'::jsonb, 'qr:dh53')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 2, content_url = 'qr:dh53';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 5.3 — Biên soạn bảng hợp âm', 20, 'published', $json$[{"id":"s172","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Một bản hợp âm chép lộn xộn rất khó đàn. Hãy trình bày lại cho sạch.</p>"},{"id":"s173","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Viết lại bài ở tông đã chọn, ghi hợp âm đúng chỗ đổi, gọn gàng dễ đọc. Bài mẫu dùng bốn hợp âm quen thuộc: C, Am, Fmaj7, G7.</p>"},{"id":"s174","order":3,"logic":"NHAN","type":"guitar_chord","title":"Hợp âm C","interactive":{"name":"C","frets":[-1,3,2,0,1,0],"freqs":[0,130.81,164.81,196,261.63,329.63],"caption":"C (Đô trưởng) — bass ở dây 5. Ngón 1 dây 2/f1, ngón 2 dây 4/f2, ngón 3 dây 5/f3. Bấm <b>Nghe</b> rồi gảy thử trên đàn."}},{"id":"s175","order":4,"logic":"NHAN","type":"guitar_chord","title":"Hợp âm Am","interactive":{"name":"Am","frets":[-1,0,2,2,1,0],"freqs":[0,110,164.81,220,261.63,329.63],"caption":"Am (La thứ) — bass ở dây 5. Ngón 1 dây 2/f1, ngón 2 dây 4/f2, ngón 3 dây 3/f2. Bấm <b>Nghe</b> rồi gảy thử trên đàn."}},{"id":"s176","order":5,"logic":"NHAN","type":"guitar_chord","title":"Hợp âm Fmaj7","interactive":{"name":"Fmaj7","frets":[-1,-1,3,2,1,0],"freqs":[0,0,174.61,220,261.63,329.63],"caption":"Fmaj7 — bass ở dây 4; giữ ngón 1 làm điểm tựa với C. Bấm <b>Nghe</b> rồi gảy thử trên đàn."}},{"id":"s177","order":6,"logic":"NHAN","type":"guitar_chord","title":"Hợp âm G7","interactive":{"name":"G7","frets":[3,2,0,0,0,1],"freqs":[98,123.47,146.83,196,246.94,349.23],"caption":"G7 — bass ở dây 6, quạt đủ 6 dây. Bấm <b>Nghe</b> rồi gảy thử trên đàn."}},{"id":"s178","order":7,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Bảng gọn giúp mắt đọc trước một bước, để tay trái kịp chuẩn bị hợp âm sắp tới.</p>"},{"id":"s179","order":8,"logic":"NHAN","type":"text","title":"② Học","content":"<div style='background:#F3E9F0; border-left:4px solid #9C4668; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#9C4668; margin-bottom:6px;'>Nếu gặp một hợp âm chưa biết</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'>Đừng bỏ bài. Làm theo: 1) Xác định tên hợp âm. 2) Tra cứu thế bấm trên Internet. 3) Chọn nguồn đáng tin cậy. 4) Đọc sơ đồ. 5) Bấm thử, gảy rời kiểm tra từng dây. 6) Luyện chuyển với một hợp âm quen. 7) Đưa vào bài, đặt đúng phách. — Người đệm hát không cần biết sẵn mọi hợp âm, nhưng phải biết làm gì khi gặp một hợp âm mới.</div></div>"},{"id":"s180","order":9,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Có một bảng hợp âm sạch, dễ đọc; và biết cách tra cứu khi gặp một hợp âm chưa biết.</b></div></div>"}]$json$::jsonb);

  -- Bài 5.4 — Tìm phách rồi điền vào lời  (dh54)
  v_les := 'd1c00504-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 5.4 — Tìm phách rồi điền vào lời', 'flow', 3, 'free', '[]'::jsonb, 'qr:dh54')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 3, content_url = 'qr:dh54';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 5.4 — Tìm phách rồi điền vào lời', 20, 'published', $json$[{"id":"s181","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Mở một bài hát bạn thích, vừa nghe vừa vỗ tay. Vỗ vào đâu thấy “chắc tay” nhất? Đó là phách mạnh; những tiếng nhẹ xen giữa là phách nhẹ.</p>"},{"id":"s182","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bước 1 — phách MẠNH bằng mắt</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'>Nhìn bản nhạc: số chỉ nhịp (2/4, 3/4, 4/4…) và các vạch nhịp. Ngay sau mỗi vạch nhịp là phách 1 — phách mạnh của ô. Chưa cần đọc hết tiết tấu; chỉ cần thấy cấu trúc ô nhịp để biết nhịp bắt đầu ở đâu.</div></div>"},{"id":"s183","order":3,"logic":"NHAN","type":"text","title":"② Học","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bước 2 — phách NHẸ bằng tai</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'>Phách nhẹ khó “đọc” hết bằng ký hiệu ở trình độ này. Hãy tự hát → vỗ tay → nghe → cảm nhận. Để ý ca sĩ bắt đầu tiếng ở đâu, kéo dài ở đâu, câu hát “rơi” vào đâu. <b>Phách mạnh tìm bằng mắt; phách nhẹ phải học cách tìm bằng tai.</b></div></div>"},{"id":"s184","order":4,"logic":"LAM","type":"guitar_metronome","title":"Metronome","interactive":{"tempo":70,"beatsPerBar":4,"caption":"④⑤ Metronome: khi đã cảm được phách, điền số phách cho lời và đánh dấu chỗ đổi hợp âm — kể cả khi đổi giữa câu."}},{"id":"s185","order":5,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Nhìn bản nhạc tìm được phách mạnh; hát + vỗ tay + nghe để cảm phách nhẹ; rồi điền phách vào lời và xác định đúng chỗ đổi hợp âm (kể cả đổi giữa câu).</b></div></div>"}]$json$::jsonb);

  -- Bài 5.5 — Chưa được cầm đàn  (dh55)
  v_les := 'd1c00505-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 5.5 — Chưa được cầm đàn', 'flow', 4, 'free', '[]'::jsonb, 'qr:dh55')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 4, content_url = 'qr:dh55';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 5.5 — Chưa được cầm đàn', 20, 'published', $json$[{"id":"s186","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Cất đàn sang một bên. Chỉ hát + vỗ tay + metronome.</p>"},{"id":"s187","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Làm cho bài hát chạy đúng nhịp bằng giọng trước. Tay vỗ giữ phách, metronome giữ đều, miệng hát theo bảng phách đã điền.</p>"},{"id":"s188","order":3,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Nếu chưa hát trôi được trong nhịp, cầm đàn vào sẽ càng loạn. Giọng phải chạy được trước — cây đàn chỉ vào khi bài đã vững.</p>"},{"id":"s189","order":4,"logic":"LAM","type":"guitar_metronome","title":"Metronome","interactive":{"tempo":70,"beatsPerBar":4,"caption":"⑤ Metronome giữ nhịp; hát cả bài + vỗ tay tới khi trôi chảy, đúng nhịp. Nếu có, thu âm phần hát + vỗ tay rồi nghe lại."}},{"id":"s190","order":5,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Hát trôi chảy cả bài đúng nhịp cùng vỗ tay và metronome — chưa cần đàn.</b></div></div>"}]$json$::jsonb);

  -- Bài 5.6 — Vào hát từ hợp âm  (dh56)
  v_les := 'd1c00506-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 5.6 — Vào hát từ hợp âm', 'flow', 5, 'free', '[]'::jsonb, 'qr:dh56')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 5, content_url = 'qr:dh56';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 5.6 — Vào hát từ hợp âm', 20, 'published', $json$[{"id":"s191","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Quạt hợp âm đầu bài, rồi thử cất giọng vào. Bạn có vào đúng tông không, hay bị chênh?</p>"},{"id":"s192","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Nghe hợp âm đang vang, tìm trong đó một nốt làm “điểm tựa”, ngân nhẹ (như tiếng “ừm” ở Level 1), rồi vào câu hát từ nốt đó.</p>"},{"id":"s193","order":3,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Hợp âm cho bạn một “nốt mồi” để vào hát đúng cao độ — không phải đoán mò rồi chênh.</p>"},{"id":"s194","order":4,"logic":"LAM","type":"guitar_listen","title":"Nghe & chọn","interactive":{"question":"Để cất giọng vào ĐÚNG cao độ, nên làm gì trước?","plays":[{"label":"Nghe hợp âm đầu (Am)","chords":[[110,164.81,220,261.63,329.63]]}],"options":["Đoán đại rồi hát","Nghe hợp âm, lấy một nốt trong đó làm “điểm tựa” rồi vào","Hát thật to cho chắc"],"answer":1,"explain":"Hợp âm đang vang cho bạn một “nốt mồi”. Ngân nhẹ nốt đó (như tiếng “ừm” ở Level 1) rồi vào câu hát — không bị chênh. Có video hướng dẫn mẫu."}},{"id":"s195","order":5,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Vào câu hát đúng cao độ nhờ nghe hợp âm và lấy một nốt trong đó làm điểm tựa.</b></div></div>"}]$json$::jsonb);

  -- Bài 5.7 — Tìm nơi bài hát muốn “về”  (dh57)
  v_les := 'd1c00507-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 5.7 — Tìm nơi bài hát muốn “về”', 'flow', 6, 'free', '[]'::jsonb, 'qr:dh57')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 6, content_url = 'qr:dh57';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 5.7 — Tìm nơi bài hát muốn “về”', 20, 'published', $json$[{"id":"s196","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Hát hoặc đàn hết bài, để ý: chỗ nào cho bạn cảm giác “xong, đã về nhà”?</p>"},{"id":"s197","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Chỗ đó là âm chủ / hợp âm chủ — chính là “điểm về nhà” bạn đã cảm ở Level 3, nay áp cho cả một bài hát. Thường là hợp âm bài kết thúc.</p>"},{"id":"s198","order":3,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Biết hợp âm chủ giúp bạn tạo cảm giác kết đúng chỗ và biết bài “về” đâu — rất cần khi tự đệm.</p>"},{"id":"s199","order":4,"logic":"LAM","type":"guitar_listen","title":"Nghe & chọn","interactive":{"question":"Nghe và cảm nhận: hợp âm nào cho cảm giác bài “đã kết, về nhà”?","plays":[{"label":"Nghe kết về C","chords":[[146.83,220,293.66,349.23],[98,123.47,146.83,196,246.94,349.23],[130.81,164.81,196,261.63,329.63]]}],"options":["C","G7","Dm"],"answer":0,"explain":"Chỗ cho cảm giác “xong, ổn” là âm chủ / hợp âm chủ — thường là hợp âm bài kết thúc. Biết nó giúp tạo cảm giác kết đúng chỗ."}},{"id":"s200","order":5,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Nhận ra âm chủ/hợp âm chủ của bài và cảm nhận được điểm kết.</b></div></div>"}]$json$::jsonb);

  -- Bài 5.8 — Ghép đàn  (dh58)
  v_les := 'd1c00508-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 5.8 — Ghép đàn', 'flow', 7, 'free', '[]'::jsonb, 'qr:dh58')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 7, content_url = 'qr:dh58';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 5.8 — Ghép đàn', 30, 'published', $json$[{"id":"s201","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Bây giờ mới cầm đàn — đưa quạt và hợp âm vào bài bạn ĐÃ chuẩn bị.</p>"},{"id":"s202","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Bài đã chạy được bằng giọng + nhịp. Cây đàn giờ chỉ làm ba việc: giữ nhịp, đưa hợp âm vào đúng phách đã điền, và nâng đỡ giọng hát.</p>"},{"id":"s203","order":3,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Vì đã chuẩn bị kỹ, cây đàn không phải “tìm đường” nữa. Bạn đã biết bài đi thế nào — đàn chỉ việc theo.</p>"},{"id":"s204","order":4,"logic":"LAM","type":"guitar_metronome","title":"Metronome","interactive":{"tempo":70,"beatsPerBar":4,"caption":"⑤ Backing/metronome nền: hát + đệm cả bài; đổi hợp âm đúng phách đã điền, tay phải giữ đều. Có <b>video hướng dẫn mẫu</b> cách ghép đàn."}},{"id":"s205","order":5,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Vừa hát vừa tự đệm trôi chảy bài đã chuẩn bị, hợp âm vào đúng phách, nhịp không vỡ.</b></div></div>"}]$json$::jsonb);

  -- Bài 5.9 — Một bài hát hoàn toàn mới (Capstone)  (dh59)
  v_les := 'd1c00509-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Bài 5.9 — Một bài hát hoàn toàn mới (Capstone)', 'flow', 8, 'free', '[]'::jsonb, 'qr:dh59')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 8, content_url = 'qr:dh59';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Bài 5.9 — Một bài hát hoàn toàn mới (Capstone)', 50, 'published', $json$[{"id":"s206","order":1,"logic":"DAN","type":"text","title":"① Khám phá","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Chọn một bài bạn chưa từng đệm. Không học thuộc trước — bạn sẽ tự xử lý nó.</p>"},{"id":"s207","order":2,"logic":"NHAN","type":"text","title":"② Học","content":"<div style='background:#FBF6ED; border-left:4px solid #BF5A37; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#BF5A37; margin-bottom:6px;'>Checklist quy trình</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'>1) Chọn tông dễ (Am/C). 2) Chọn capo hợp giọng. 3) Chỉnh & tra cứu hợp âm (gặp hợp âm lạ thì tra thế bấm). 4) Xác định nhịp. 5) Tìm phách mạnh (nhìn sheet). 6) Tìm phách nhẹ (hát + vỗ tay + nghe). 7) Điền phách vào lời. 8) Xác định điểm đổi hợp âm. 9) Hát + vỗ tay + metronome (chưa đàn). 10) Vào câu hát đúng cao độ. 11) Nhận âm chủ / hợp âm chủ. 12) Ghép đàn → tự đệm hoàn chỉnh.</div></div>"},{"id":"s208","order":3,"logic":"NGHI","type":"text","title":"③ Hiểu","content":"<p style='font-size:16px; line-height:1.7; margin:0 0 12px; color:#3A352F;'>Đây là đích của cả Đệm hát 1: bạn không cần thuộc bài trước, vẫn tự đệm được một bài mới.</p>"},{"id":"s209","order":4,"logic":"LAM","type":"guitar_metronome","title":"Metronome","interactive":{"tempo":70,"beatsPerBar":4,"caption":"⑤ Làm đủ 12 bước trên một bài mới → đệm hoàn chỉnh. Tự chấm từng bước; nghe lại bản đệm của mình."}},{"id":"s210","order":5,"logic":"DAN","type":"text","title":"⑥ Đạt","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Bạn đạt bài này khi…</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'><b>Nhận một bài chưa từng học và tự: tông/capo → chỉnh & tra cứu hợp âm lạ → xác định nhịp → tìm phách mạnh (mắt) và phách nhẹ (tai) → điền phách & điểm đổi → hát+vỗ tay+metronome → vào câu hát đúng cao độ → nhận âm chủ → ghép đàn & đệm hoàn chỉnh.</b></div></div>"}]$json$::jsonb);

  -- Tự kiểm Level 5  (dh5check)
  v_les := 'd1c00599-0000-4000-8000-000000000000';
  INSERT INTO edu_course_lessons (id, module_id, title, lesson_type, order_index, tier, tools, content_url)
    VALUES (v_les, v_mod, 'Tự kiểm Level 5', 'flow', 9, 'free', '[]'::jsonb, 'qr:dh5check')
    ON CONFLICT (id) DO UPDATE SET module_id = v_mod, title = EXCLUDED.title, lesson_type = 'flow', order_index = 9, content_url = 'qr:dh5check';
  DELETE FROM flows WHERE lesson_id = v_les;
  INSERT INTO flows (lesson_id, title, reward_xp, status, slides) VALUES (
    v_les, 'Tự kiểm Level 5', 20, 'published', $json$[{"id":"s211","order":1,"logic":"DAN","type":"text","title":"Tự kiểm","content":"<div style='background:#EAF3F1; border-left:4px solid #3E7C74; border-radius:6px; padding:14px 16px;'><div style='font-size:11px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; color:#3E7C74; margin-bottom:6px;'>Đánh dấu khi bạn làm được</div><div style='font-size:16px; line-height:1.65; color:#2A2622;'>Chỗ nào chưa đạt, quay lại đúng bài rèn năng lực đó. Khi cả bảng đều đạt, bạn sẵn sàng cho Level tiếp theo.</div></div>"},{"id":"s212","order":2,"logic":"NGAM","type":"checklist","title":"Bảng tự kiểm","interactive":{"items":["Đưa được một bài về tông Am hoặc C","Chọn được capo hợp giọng (thử & nghe)","Có bảng hợp âm sạch, dễ đọc","Điền được số phách vào lời","Xác định đúng chỗ đổi hợp âm trong lời","Hát + vỗ tay + metronome trôi chảy (chưa đàn)","Vào câu hát đúng cao độ nhờ nghe hợp âm","Nhận ra âm chủ/hợp âm chủ, tạo được cảm giác kết","Tự chuẩn bị & đệm trọn một bài mới"]}}]$json$::jsonb);

  RAISE NOTICE 'DH1 restructure xong. Nhớ trỏ QR về lesson id (phần dưới).';
END $$;

NOTIFY pgrst, 'reload schema';

-- ── Trỏ QR sách về đúng bài (thay đích tạm /start) ──────────────────────────
-- Chạy SAU qr_links_demhat.sql. content_url mỗi bài = 'qr:<slug>' để tra ngược.
UPDATE qr_links q SET target = '/course?id=' || l.id
  FROM edu_course_lessons l
  WHERE l.content_url = 'qr:' || q.slug AND q.slug LIKE 'dh%';

NOTIFY pgrst, 'reload schema';

-- ============================================================================
-- XOÁ HẲN 3 chương cũ (quyết định của thầy 13/08/2026). GIỮ: "Kiểm tra đầu vào"
-- + Level 3 (module vòng hoà âm 319654a9 tái dùng làm Level 3). Xoá theo ID cố
-- định để KHÔNG đụng nhầm module khác. Thứ tự theo FK: flows → bài → module.
-- ⚠️ Mất tiến độ/XP học viên ở các bài này (không khôi phục được) — thầy đã đồng ý.
-- ----------------------------------------------------------------------------
DO $$
DECLARE
  v_old uuid[] := ARRAY[
    'd23be114-45ec-4b2c-bcb2-ce9cbcd9f436',  -- Chương 1: Hợp âm
    '2b1a0bcf-f90f-4c3f-ad8b-b5beecb8db3e',  -- Chương 2: Quạt hợp âm
    'f9fb42d8-df87-4636-839f-3e1d6d338012'   -- Chương 4: Kiến thức nhịp phách
  ]::uuid[];
BEGIN
  DELETE FROM flows WHERE lesson_id IN (SELECT id FROM edu_course_lessons WHERE module_id = ANY(v_old));
  DELETE FROM edu_course_lessons WHERE module_id = ANY(v_old);
  DELETE FROM edu_modules WHERE id = ANY(v_old);
  RAISE NOTICE 'Đã xoá 3 chương cũ (Hợp âm/Quạt/Nhịp phách).';
END $$;

NOTIFY pgrst, 'reload schema';
